# compute girth
from collections import deque
def girth(adj, n):
    g = float('inf')
    for s in range(n):
        dist = {s:0}
        parent = {s:-1}
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u]+1
                    parent[v] = u
                    q.append(v)
                elif parent[u] != v:
                    # found cycle
                    c = dist[u]+dist[v]+1
                    if c < g: g = c
    return g

print("girth:", girth(adj, n))

# 4-color with backtracking
def color(adj, n, k):
    col = [-1]*n
    order = sorted(range(n), key=lambda x: -len(adj[x]))
    def bt(idx):
        if idx == n: return True
        v = order[idx]
        used = {col[u] for u in adj[v] if col[u]>=0}
        for c in range(k):
            if c not in used:
                col[v]=c
                if bt(idx+1): return True
                col[v]=-1
        return False
    if bt(0): return col
    return None

